<?php
session_start();
require_once '../config/database.php';
if (!isset($_SESSION['user_id']) || $_SESSION['role'] !== 'admin') { header('Location: ../login.php'); exit(); }
$id=(int)($_GET['id']??$_POST['id']??0); if($id<=0){header('Location: products.php');exit();}
$s=$conn->prepare('SELECT * FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();$product=$s->get_result()->fetch_assoc();if(!$product){header('Location: products.php');exit();}
function admin_upload($file,&$error=''){if(!isset($file)||$file['error']===UPLOAD_ERR_NO_FILE)return null;if($file['error']!==UPLOAD_ERR_OK){$error='Image upload failed.';return null;}if($file['size']>5*1024*1024){$error='Image must be 5 MB or smaller.';return null;}$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp','gif'],true)){$error='Only JPG, JPEG, PNG, WEBP and GIF images are allowed.';return null;}if(@getimagesize($file['tmp_name'])===false){$error='Please upload a valid image.';return null;}$dir=__DIR__.'/../assets/uploads/';if(!is_dir($dir))@mkdir($dir,0755,true);$name=date('YmdHis').'_'.bin2hex(random_bytes(6)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.$name)){$error='Could not save image.';return null;}return $name;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$category=trim($_POST['category']??'');$status=$_POST['status']??'active';$new=admin_upload($_FILES['image']??null,$error);if(!$name||$price<0||$stock<0){$error='Please enter valid product details.';}elseif(!$error){if($new){$u=$conn->prepare('UPDATE products SET name=?,description=?,price=?,stock=?,image=?,category=?,status=? WHERE id=?');$u->bind_param('ssdisssi',$name,$description,$price,$stock,$new,$category,$status,$id);}else{$u=$conn->prepare('UPDATE products SET name=?,description=?,price=?,stock=?,category=?,status=? WHERE id=?');$u->bind_param('ssdissi',$name,$description,$price,$stock,$category,$status,$id);}if($u->execute()){if($new&&!empty($product['image'])&&is_file(__DIR__.'/../assets/uploads/'.$product['image']))@unlink(__DIR__.'/../assets/uploads/'.$product['image']);header('Location: products.php');exit();}$error='Could not update product: '.$u->error;$product=array_merge($product,['name'=>$name,'description'=>$description,'price'=>$price,'stock'=>$stock,'category'=>$category,'status'=>$status]);}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Product - Bazario Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"><link href="../assets/css/theme.css" rel="stylesheet"><style>body{min-height:100vh}.edit-card{max-width:900px;margin:40px auto}.form-control,.form-select{color:#fff;background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.25)}.form-select option{color:#111}.current-img{width:100%;max-height:300px;object-fit:contain;background:rgba(0,0,0,.15);border-radius:15px}.btn-brand{background:var(--neon-accent);color:#fff;border:0}</style></head><body><div class="animated-bg"></div><div class="container"><div class="glass-card edit-card p-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="text-white mb-1"><i class="fas fa-pen me-2"></i>Edit Product</h2><p class="text-white-50 mb-0">Update product information or replace its image.</p></div><a href="products.php" class="btn glass-card text-white border-0">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-4"><div class="col-md-8"><label class="form-label">Product name</label><input class="form-control" name="name" value="<?=htmlspecialchars($product['name'])?>" required></div><div class="col-md-4"><label class="form-label">Category</label><input class="form-control" name="category" value="<?=htmlspecialchars($product['category']??'')?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="5"><?=htmlspecialchars($product['description']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Price (₹)</label><input class="form-control" name="price" type="number" min="0" step="0.01" value="<?=htmlspecialchars($product['price'])?>" required></div><div class="col-md-4"><label class="form-label">Stock</label><input class="form-control" name="stock" type="number" min="0" value="<?=htmlspecialchars($product['stock'])?>" required></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=$product['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$product['status']==='inactive'?'selected':''?>>Inactive</option></select></div><div class="col-md-6"><label class="form-label">Current image</label><?php if(!empty($product['image'])&&is_file(__DIR__.'/../assets/uploads/'.$product['image'])):?><img class="current-img" src="../assets/uploads/<?=htmlspecialchars($product['image'])?>" alt="Current product image"><?php else:?><div class="current-img d-flex align-items-center justify-content-center text-white-50" style="height:250px"><i class="fas fa-image fa-3x"></i></div><?php endif;?></div><div class="col-md-6"><label class="form-label">Replace image</label><input class="form-control" name="image" type="file" accept="image/*"><p class="text-white-50 small mt-2">Leave empty to keep the current image. Maximum 5 MB.</p></div><div class="col-12"><button class="btn btn-brand btn-lg"><i class="fas fa-save me-2"></i>Save Changes</button></div></div></form></div></div></body></html>
